fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since the lengths are guaranteed equal, we can use zip to pair elements.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x < y)
     .collect()
}